import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

function Navbar({ userRole }) {
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false); // mobile menu toggle

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const toggleMenu = () => setIsOpen(!isOpen);

  return (
    <nav className="bg-white shadow">
      <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* Brand */}
        <Link to="/dashboard" className="text-2xl font-bold text-blue-600">
          CampusConnect
        </Link>

        {/* Hamburger for mobile */}
        <div className="md:hidden">
          <button
            onClick={toggleMenu}
            className="text-gray-700 hover:text-blue-600 focus:outline-none"
          >
            {isOpen ? (
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            ) : (
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8h16M4 16h16" />
              </svg>
            )}
          </button>
        </div>

        {/* Menu */}
        <ul
          className={`flex-col md:flex md:flex-row md:items-center md:gap-6 absolute md:static top-full left-0 w-full md:w-auto bg-white md:bg-transparent transition-all duration-300 overflow-hidden ${
            isOpen ? "max-h-96 py-4" : "max-h-0"
          }`}
        >
          {userRole === "student" && (
            <>
              <li>
                <Link
                  to="/dashboard"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Dashboard
                </Link>
              </li>
              <li>
                <Link
                  to="/support"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Support
                </Link>
              </li>
              <li>
                <Link
                  to="/feedback"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Feedback
                </Link>
              </li>
            </>
          )}

          {userRole === "admin" && (
            <>
              <li>
                <Link
                  to="/admin-dashboard"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Admin Dashboard
                </Link>
              </li>
              <li>
                <Link
                  to="/admin-announcements"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Announcements
                </Link>
              </li>
              <li>
                <Link
                  to="/admin-students"
                  className="block px-6 py-2 md:py-0 text-gray-700 hover:text-blue-600 relative after:absolute after:left-0 after:-bottom-1 after:h-[2px] after:w-0 after:bg-blue-600 after:transition-all after:duration-300 hover:after:w-full"
                  onClick={() => setIsOpen(false)}
                >
                  Student Profiles
                </Link>
              </li>
            </>
          )}

          {/* Logout button */}
          <li className="px-6 py-2 md:py-0">
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 w-full md:w-auto"
            >
              Logout
            </button>
          </li>
        </ul>
      </div>
    </nav>
  );
}

export default Navbar;
